package solution

import (
	"fmt"
	"testing"
)

func TestClassify(t *testing.T) {
	cases := []struct {
		name        string
		err         error
		wantCode    int
		wantRetry   int
	}{
		{"notfound", fmt.Errorf("get: %w", ErrNotFound), 404, 0},
		{"retryable", fmt.Errorf("call: %w", &RetryableError{After: 5}), 503, 5},
		{"unknown", fmt.Errorf("boom"), 500, 0},
	}
	for _, c := range cases {
		code, retry := Classify(c.err)
		if code != c.wantCode || retry != c.wantRetry {
			t.Errorf("%s: got (%d,%d) want (%d,%d)", c.name, code, retry, c.wantCode, c.wantRetry)
		}
	}
}

