import (
	"context"
	"errors"
	"fmt"
	"time"
)

type TransientError struct {
	RetryAfter time.Duration
	Err        error
}

func (e *TransientError) Error() string {
	return fmt.Sprintf("transient (retry after %s): %v", e.RetryAfter, e.Err)
}
func (e *TransientError) Unwrap() error { return e.Err }

// RetryClassifier decides whether err is worth retrying and how long to wait.
func RetryClassifier(err error) (retryable bool, retryAfter time.Duration) {
	var te *TransientError
	if errors.As(err, &te) { // typed error carries a backoff hint
		return true, te.RetryAfter
	}
	if errors.Is(err, context.DeadlineExceeded) { // sentinel: retryable, no hint
		return true, 0
	}
	return false, 0 // anything else: don't retry
}

import "fmt"

type QueryError struct {
	Query string
	Err   error
}

// Error renders a contextual message.
func (e *QueryError) Error() string {
	return fmt.Sprintf("query %q: %v", e.Query, e.Err)
}

// Unwrap exposes the cause so errors.Is/As can walk the chain.
func (e *QueryError) Unwrap() error {
	return e.Err
}
